 public static class ProductionMenuChecks {
  static int checks;
  static void Check(bool value,string why){checks++;if(!value)throw new InvalidOperationException("Production UI: "+why);}
  public static void ValidateAuthored(PrototypeHUD hud){
   var ui=hud.productionMenu;Check(ui&&hud.menuRoot==ui.gameObject,"Menu binding");Check(ui.pages.Length==10&&ui.pageNames.Distinct().Count()==10,"Screen inventory");Check(ui.vehiclePictures.Length==2&&ui.vehiclePictures.All(s=>s&&AssetDatabase.Contains(s)),"Saved vehicle captures");Check(ui.dialog&&ui.garageContent&&ui.shopContent&&ui.contentGroup,"Tabs/modal binding");
   foreach(var a in ui.GetComponentsInChildren<ProductionMenuAction>(true)){var b=a.GetComponent<Button>();Check(b&&a.menu==ui&&b.onClick.GetPersistentEventCount()==1&&b.onClick.GetPersistentTarget(0)==a&&b.onClick.GetPersistentMethodName(0)=="Click","Persistent action: "+a.name);}
   Check(ui.GetComponentsInChildren<MachinerySwipe>(true).Length==2,"Machinery and workshop swipe previews");Check(hud.panels.Length==10,"Legacy fallback retained");Check(ui.workshopPreview&&ui.workshopPreview.vehicles.All(v=>v.GetComponentsInChildren<MeshRenderer>(true).Length>0)&&ui.workshopPreview.parts.All(v=>v.GetComponentsInChildren<MeshRenderer>(true).Length>0),"Authored 3D vehicle and part meshes");Check(ui.workshopPreview.GetComponentsInChildren<Collider>(true).Length==0&&ui.workshopPreview.GetComponentsInChildren<MachineController>(true).Length==0,"Display has no physics or machinery controllers");
   Check(ui.labels.Select(x=>x.key).Distinct().Count()==ui.labels.Length,"Duplicate label keys");Check(ui.buttons.Select(x=>x.key).Distinct().Count()==ui.buttons.Length,"Duplicate button keys");
   Check(ui.quickTools&&ui.jobCards.Length==3&&ui.jobCards.All(x=>x)&&Enumerable.Range(0,3).All(i=>ui.Button("job-"+i)),"Authored Quick Play slots and controls");
  }
  public static void Run(PrototypeHUD original){
   checks=0;ValidateAuthored(original);var source=original.GetComponentInParent<Canvas>();var real=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(o=>o.GetComponentsInChildren<PrototypeSession>(true)).Single();
   var preview=EditorSceneManager.NewPreviewScene();var root=new GameObject("Disposable production UI fixture");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,preview);var field=typeof(PrototypeSession).GetField("<Instance>k__BackingField",BindingFlags.Static|BindingFlags.NonPublic);var prior=PrototypeSession.Instance;float time=Time.timeScale;
   try{
    var game=root.AddComponent<PrototypeSession>();field.SetValue(null,game);game.Profile=new ProfileSave{legacyUnlockedJobs=3};game.Input=root.AddComponent<PrototypeInput>();game.Audio=root.AddComponent<SynthAudio>();game.Audio.effects=root.AddComponent<AudioSource>();game.Audio.effects.mute=true;game.Audio.chime=real.Audio.chime;game.CameraRig=real.CameraRig;game.Snow=root.AddComponent<SnowField>();game.Snow.seed=real.Snow.seed;
    game.Fleet=real.Fleet.Select(m=>{var copy=UnityEngine.Object.Instantiate(m.gameObject);copy.transform.SetParent(root.transform,false);copy.transform.position=new Vector3(-95,6,-90);var machine=copy.GetComponent<MachineController>();machine.Initialize();machine.Owned=!machine.definition.loader;machine.Fuel=machine.definition.fuelCapacity*.5f;machine.Condition=80;return machine;}).ToArray();
    var canvas=UnityEngine.Object.Instantiate(source.gameObject);canvas.transform.SetParent(root.transform,false);game.HUD=canvas.GetComponent<PrototypeHUD>();var ui=game.HUD.productionMenu;var display=UnityEngine.Object.Instantiate(original.productionMenu.workshopPreview.gameObject);display.transform.SetParent(root.transform,true);ui.workshopPreview=display.GetComponent<WorkshopPreview>();ui.gameObject.SetActive(true);ValidateAuthored(game.HUD);
    game.Open("dashboard");Check(!game.IsRunning&&Time.timeScale==0,"Home pauses");ui.Execute("career");Check(ui.ScreenName=="regions","Career route");
    for(int r=0;r<5;r++){ui.Execute("region:"+r);Check(ui.ScreenName=="towns","Town route");for(int i=0;i<ProductionMenu.Destinations[r].Length;i++)Check(ui.Button("town-"+i).interactable==(r==0&&i==0),"Planned town gate");}
    ui.Execute("region:0");ui.Execute("town:0");Check(game.Panel=="contracts","Pinefall route");ui.Execute("job:1");Check(game.IsRunning&&game.Profile.inJob&&game.Profile.job==1&&game.Profile.active==0,"Career starts directly with selected tractor");string oldTransaction=game.Profile.transaction;int oldCoins=game.Profile.coins;float oldFuel=game.Active.Fuel,oldCondition=game.Active.Condition,oldTime=game.Profile.remaining;game.Open("contracts");ui.Execute("job:2");Check(ui.PendingConfirmation=="replace-job"&&ui.dialog.activeSelf&&!ui.contentGroup.interactable,"Active job conflict dialog blocks underlying controls");Check(game.Profile.job==1&&game.Profile.transaction==oldTransaction&&game.Profile.remaining==oldTime&&game.Profile.coins==oldCoins,"Request preserves current progress and rewards");Check(ui.Button("dialog-close")&&ui.Label("cancel").text=="Continue Current Job"&&ui.Label("accept").text=="Abandon & Start New Job","Conflict actions and close icon");Capture(game.HUD,"job-conflict",1280,720);ui.Execute("cancel");Check(!ui.dialog.activeSelf&&game.Panel=="contracts"&&game.Profile.transaction==oldTransaction,"Close leaves current job and job list intact");ui.Execute("job:2");ui.Execute("dialog-secondary");Check(game.IsRunning&&game.Profile.job==1&&game.Profile.transaction==oldTransaction,"Continue resumes pending job");game.Open("contracts");ui.Execute("free");Check(ui.PendingConfirmation=="replace-job","Free Work also prompts");ui.Execute("accept");Check(game.IsRunning&&game.Profile.inJob&&game.Profile.freeWork&&game.Profile.job==0&&game.Profile.transaction!=oldTransaction,"Abandon starts requested Free Work");Check(game.Profile.coins==oldCoins&&game.Active.Fuel==oldFuel&&game.Active.Condition==oldCondition&&game.Profile.active==0,"Replacement preserves funds and vehicle state");string replacement=game.Profile.transaction;ui.Execute("accept");Check(game.Profile.transaction==replacement,"Duplicate replacement acceptance inert");game.Open("contracts");ui.Execute("job:2");ui.Execute("accept");Check(game.IsRunning&&!game.Profile.freeWork&&game.Profile.job==2&&game.Profile.transaction!=replacement,"Abandon starts requested contract");game.Open("contracts");ui.Execute("job:2");Check(ui.dialog.activeSelf,"Restart same contract also requires consent");ui.Execute("cancel");ui.Confirm("repair");Check(ui.Label("cancel").text=="Cancel"&&ui.Label("accept").text=="Confirm"&&ui.Label("dialog-price").gameObject.activeSelf,"Regular confirmation labels restored");ui.Execute("cancel");
    game.Profile.inJob=false;game.Open("garage");int coins=game.Profile.coins;
    ui.Browse(1);Check(ui.Label("garage-name").text==game.Fleet[1].definition.displayName&&!ui.Button("drive").interactable,"Garage browses unowned vehicle");ui.Browse(1);Check(ui.Label("garage-name").text==game.Fleet[0].definition.displayName,"Garage wraps");
    var swipe=ui.GetComponentsInChildren<MachinerySwipe>(true).Single(x=>x.name=="3D vehicle and part view");var data=new PointerEventData(null){pointerId=3,position=new Vector2(600,200)};swipe.OnBeginDrag(data);data.position=new Vector2(300,200);swipe.OnEndDrag(data);Check(ui.Label("garage-name").text==game.Fleet[1].definition.displayName,"Workshop swipe left");data.position=new Vector2(300,200);swipe.OnBeginDrag(data);data.position=new Vector2(600,200);swipe.OnEndDrag(data);Check(ui.Label("garage-name").text==game.Fleet[0].definition.displayName,"Workshop swipe right");data.position=new Vector2(600,200);swipe.OnBeginDrag(data);data.position=new Vector2(601,500);swipe.OnEndDrag(data);Check(ui.Label("garage-name").text==game.Fleet[0].definition.displayName,"Vertical drag rejection");
    ui.Execute("nav:shop");Check(ui.ScreenName=="garage"&&ui.ShopTab,"Unified shop route");ui.Execute("confirm:buy");Check(ui.dialog.activeSelf&&game.Profile.coins==coins,"Purchase needs confirmation");ui.Execute("cancel");Check(!game.Fleet[1].Owned&&game.Profile.coins==coins,"Cancel purchase");ui.Execute("confirm:buy");ui.Execute("accept");Check(game.Fleet[1].Owned&&game.Profile.coins==coins-game.Fleet[1].definition.price,"Actual purchase price");int after=game.Profile.coins;ui.Execute("accept");Check(game.Profile.coins==after,"Double confirm inert");ui.Execute("owned");Check(!ui.ShopTab&&ui.garageContent.activeSelf&&!ui.shopContent.activeSelf,"Garage tab");
    ui.Execute("garage:0");ui.Execute("garage-tab:service");Check(ui.serviceContent.activeSelf&&ui.upgradesContent.activeSelf,"Garage service and upgrades visible together");int cost=ui.Quote("repair");Check(cost==60,"Repair uses live condition");ui.Execute("confirm:repair");ui.Execute("accept");Check(game.Fleet[0].Condition==100&&game.Profile.coins==after-cost,"Actual repair");
    game.Fleet[0].Tyres=2;Check(ui.Quote("tyres")==600,"Upgrade level pricing");game.Fleet[0].Tyres=3;ui.Refresh();Check(!ui.Button("tyres").interactable,"Upgrade max gate");
    ui.Execute("garage:1");ui.Execute("drive");Check(game.Profile.active==1&&!game.IsRunning,"Garage selection without a job stays in menus");ui.Execute("quick");Check(game.Panel=="contracts","Quick Job job list");int shuffledKind=ui.JobAtSlot(2).Value.kind;ui.Execute("job:2");Check(game.Profile.inJob&&game.Profile.job==shuffledKind&&game.Profile.quickPlay&&game.Profile.active==1&&game.IsRunning&&Time.timeScale==1,"Actual loader job start");Check(game.HUD.driving.activeSelf&&!game.HUD.menuRoot.activeSelf,"Driving preserved");
    game.Open("pause");Check(Time.timeScale==0&&!game.HUD.driving.activeSelf,"Pause screen");ui.Execute("continue");Check(game.IsRunning&&Time.timeScale==1,"Resume");game.Open("shop");Check(ui.ShopTab&&Time.timeScale==0,"Shop pauses");
    game.Profile.coins=0;ui.Execute("garage:0");game.Fleet[0].Condition=50;ui.Execute("confirm:repair");Check(!ui.Button("accept").interactable,"Insufficient currency confirmation");ui.Execute("cancel");
    foreach(var name in ui.pageNames){game.Open(name);ui.Refresh();Check(ui.pages.Count(p=>p.activeSelf)==1,"Only one screen: "+name);Canvas.ForceUpdateCanvases();foreach(var button in ui.GetComponentsInChildren<Button>()){if(!button.gameObject.activeInHierarchy)continue;var corners=new Vector3[4];((RectTransform)button.transform).GetWorldCorners(corners);foreach(var corner in corners){var point=game.HUD.layout.InverseTransformPoint(corner);Check(point.x>=-641&&point.x<=641&&point.y>=-361&&point.y<=361,"Control outside design: "+button.name+" "+point);}}}
    foreach(var name in new[]{"dashboard","regions","towns","contracts","machinery","garage","shop","settings","pause","results"}){game.Open(name);Capture(game.HUD,name,1280,720);}
    game.Open("garage");Capture(game.HUD,"garage-wide",1920,1080);ui.Execute("workshop:shop");ui.Browse(1);Check(ui.PartIndex==1&&ui.Label("part-description").text.Contains("+18%"),"Engine part browse");Capture(game.HUD,"shop-engine",1280,720);Check(ui.workshopPreview.vehicles.All(x=>!x.activeSelf)&&ui.workshopPreview.parts.Count(x=>x.activeSelf)==1,"Only selected part visible");game.Profile.coins=1200;int priorEngine=game.Fleet[1].Engine;ui.Execute("buy-part");ui.Execute("accept");Check(game.Fleet[1].Engine==priorEngine+1&&game.Profile.coins==1000,"Shop buys compatible engine at live price");ui.Execute("accept");Check(game.Profile.coins==1000,"Part duplicate acceptance inert");game.Open("dashboard");Check(!ui.workshopPreview.previewCamera.enabled,"Preview camera disabled outside Garage");
    game.Open("garage");Check(!ui.Button("shop-transactions").gameObject.activeInHierarchy,"Test transactions hidden in Garage tab");ui.Execute("workshop:shop");Check(ui.Button("shop-transactions").gameObject.activeInHierarchy,"Shop exposes test transactions");int beforeDummy=game.Profile.coins;ui.Button("shop-transactions").GetComponent<ProductionMenuAction>().Click();Check(game.Panel=="store"&&game.Profile.coins==beforeDummy,"Shop opens simulated store without charging");ui.Execute("dummy:new");ui.Execute("dummy:success");Check(game.Profile.coins==beforeDummy+2000,"Dummy success grants test coins");ui.Execute("dummy:success");Check(game.Profile.coins==beforeDummy+2000,"Dummy redelivery grants once");ui.Execute("dummy:new");ui.Execute("dummy:cancel");ui.Execute("dummy:success");Check(game.Profile.coins==beforeDummy+2000,"Cancelled dummy transaction grants nothing");ui.Execute("dummy:new");ui.Execute("dummy:fail");ui.Execute("dummy:success");Check(game.Profile.coins==beforeDummy+2000,"Failed dummy transaction grants nothing");ui.Button("store-back").GetComponent<ProductionMenuAction>().Click();Check(ui.ScreenName=="garage"&&ui.ShopTab,"Simulated store returns to Shop");Capture(game.HUD,"shop-transactions",1280,720);
    GameFlowChecks.Run(game,ui);
    File.WriteAllText(ProductionMenuAuthoring.Folder+"/Checks.txt","PASS: "+checks+" authored and actual-session fixture checks. Direct Career and Quick Job startup with selected vehicle, all planned location gates, Garage and part carousel/swipes/vertical rejection, ownership, purchase/cancel/double confirmation, real repair/upgrade quotes, actual loader job start, pause/resume, insufficient funds, saved references and screen control bounds. Ten native screen renders plus 1920x1080 garage. Fixture ready=false; no player-save writes. Actual phone touch and Play traversal remain untested.");
   }finally{field.SetValue(null,prior);Time.timeScale=time;EditorSceneManager.ClosePreviewScene(preview);}
  }
  public static void Capture(PrototypeHUD hud,string name,int width,int height){
   var canvas=hud.GetComponent<Canvas>();foreach(var t in hud.GetComponentsInChildren<Transform>(true))if(!t.GetComponentInParent<WorkshopPreview>())t.gameObject.layer=5;var parent=canvas.transform.parent;var fixtureScene=canvas.gameObject.scene;canvas.transform.SetParent(null,false);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(canvas.gameObject,UnityEngine.SceneManagement.SceneManager.GetActiveScene());
   var obj=new GameObject("Temporary UI capture camera");var camera=obj.AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.gray;camera.cullingMask=1<<5;camera.orthographic=true;camera.nearClipPlane=.1f;camera.farClipPlane=100;obj.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();
   var target=new RenderTexture(width,height,24);var old=RenderTexture.active;var texture=new Texture2D(width,height,TextureFormat.RGB24,false);var mode=canvas.renderMode;var oldCamera=canvas.worldCamera;
   try{
    camera.targetTexture=target;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=10;
    foreach(var graphic in hud.GetComponentsInChildren<Graphic>())graphic.SetAllDirty();Canvas.ForceUpdateCanvases();
    File.WriteAllText(ProductionMenuAuthoring.Folder+"/RenderDiagnostic.txt","active "+canvas.gameObject.activeInHierarchy+" enabled "+canvas.enabled+" rect "+((RectTransform)canvas.transform).rect+" ui "+hud.productionMenu.gameObject.activeInHierarchy+" position "+hud.productionMenu.transform.position+" scale "+hud.productionMenu.transform.lossyScale+" camera "+camera.pixelRect+" graphics "+hud.GetComponentsInChildren<Graphic>().Length);
    var display=hud.productionMenu.workshopPreview;var displayParent=display.transform.parent;display.transform.SetParent(null,true);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(display.gameObject,UnityEngine.SceneManagement.SceneManager.GetActiveScene());if(display.gameObject.activeInHierarchy){display.previewCamera.Render();var rendered=new Texture2D(768,288,TextureFormat.RGB24,false);RenderTexture.active=display.previewCamera.targetTexture;rendered.ReadPixels(new Rect(0,0,768,288),0,0);rendered.Apply();var pixels=rendered.GetPixels32();var background=pixels[0];Check(pixels.Count(p=>Math.Abs(p.r-background.r)+Math.Abs(p.g-background.g)+Math.Abs(p.b-background.b)>20)>2000,"3D workshop image contains visible geometry");UnityEngine.Object.DestroyImmediate(rendered);}File.WriteAllText(ProductionMenuAuthoring.Folder+"/PreviewDiagnostic.txt",string.Join("\n",hud.productionMenu.workshopPreview.GetComponentsInChildren<Renderer>(true).Select(r=>r.name+" active="+r.gameObject.activeInHierarchy+" layer="+r.gameObject.layer+" bounds="+r.bounds))+"\nCamera "+hud.productionMenu.workshopPreview.previewCamera.transform.position+" scale "+hud.productionMenu.workshopPreview.previewCamera.transform.lossyScale);camera.Render();RenderTexture.active=target;texture.ReadPixels(new Rect(0,0,width,height),0,0);texture.Apply();
    File.WriteAllBytes(ProductionMenuAuthoring.Folder+"/"+name+".png",texture.EncodeToPNG());Check(texture.GetPixels32().Count(p=>Math.Abs(p.r-p.b)>8)>width*height/4,"UI render is empty: "+name);
   }finally{
    var display=hud.productionMenu.workshopPreview;UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(display.gameObject,fixtureScene);display.transform.SetParent(parent,true);canvas.renderMode=mode;canvas.worldCamera=oldCamera;RenderTexture.active=old;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(texture);target.Release();UnityEngine.Object.DestroyImmediate(target);UnityEngine.Object.DestroyImmediate(obj);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(canvas.gameObject,fixtureScene);canvas.transform.SetParent(parent,false);
   }
  }
 }
